//! The SDK of api.json, generated by flowapi's Rust target into OUT_DIR as `api.rs`.

fn main() {
    println!("cargo::rerun-if-changed=api.json");
    let text = std::fs::read_to_string("api.json").expect("api.json is readable");
    let mut docs = flowapi::Documents::new();
    docs.add("file:///api.json", &text)
        .expect("api.json is JSON");
    let (output, _) = flowapi::generate(&docs, &flowapi_rust::Rust::new("api.rs").with_sdk());
    let text: String = output
        .expect("an output")
        .files
        .into_iter()
        .map(|f| f.text)
        .collect();
    let out = std::env::var("OUT_DIR").expect("OUT_DIR");
    std::fs::write(std::path::Path::new(&out).join("api.rs"), text).expect("api.rs is writable");
}
